import { notFound } from "next/navigation";
import ProductPageView from "../../../components/ProductPage/ProductPageView";
import { fetchProductBySlug } from "../../../api/product/productApi";

type ProductPageProps = {
  params: Promise<{
    slug: string;
  }>;
};

// Разрешаем динамические параметры для статического экспорта
export const dynamicParams = true;

// Для статического экспорта требуется generateStaticParams
// Возвращаем пустой массив, так как мы не знаем все slug заранее
// Страницы будут генерироваться динамически при запросе
export const generateStaticParams = async () => {
  return [];
};

const ProductPage = async ({ params }: ProductPageProps) => {
  const { slug } = await params;

  const product = await fetchProductBySlug(slug);

  if (!product) {
    notFound();
  }

  return <ProductPageView product={product} />;
};

export default ProductPage;

